function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }

const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE returned only ' + pipe.length + ' rows'); }

// firms that appear anywhere on the corrections sheet
const corrected = {};
for (const r of $('Read Thesis correction').all()) {
  const v = Object.values(r.json).filter(function (x) { return typeof x === 'string'; });
  if (v.length > 1 && s(v[1])) { corrected[nz(v[1])] = s(v[1]); }
}
for (const r of $('Read Mail correction').all()) {
  const f = s(r.json['Firm name']);
  if (f) { corrected[nz(f)] = f; }
}

// what a 'pass' looks like in this data
const respVals = {};
const passed = {};
let passRows = 0;
for (const r of pipe) {
  const resp = s(r.investor_response);
  const reason = s(r.pass_reason);
  const status = s(r.deal_status);
  if (resp) { respVals[resp] = (respVals[resp] || 0) + 1; }
  const isPass = /pass|not relevant|not interested|decline|no fit|reject/i.test(resp + ' ' + reason + ' ' + status);
  if (!isPass) { continue; }
  passRows++;
  const inv = s(r.investor);
  if (!inv) { continue; }
  if (!passed[inv]) { passed[inv] = { investor: inv, deals: 0 }; }
  passed[inv].deals++;
}

const list = Object.keys(passed).map(function (k) {
  const nk = nz(k);
  let hit = corrected[nk] || null;
  if (!hit) {
    for (const c of Object.keys(corrected)) {
      if (c.length > 5 && (c.indexOf(nk) === 0 || nk.indexOf(c) === 0)) { hit = corrected[c]; break; }
    }
  }
  return { investor: k, passed_deals: passed[k].deals, correction_received: hit ? 'YES (' + hit + ')' : 'no' };
});
list.sort(function (a, b) { return b.passed_deals - a.passed_deals; });

const withC = list.filter(function (x) { return x.correction_received !== 'no'; });
return [{ json: {
  pass_rows: passRows,
  unique_investors_who_passed: list.length,
  of_those_with_a_correction: withC.length,
  pct: list.length ? Math.round(withC.length / list.length * 1000) / 10 : 0,
  firms_on_corrections_sheet: Object.keys(corrected).length,
  investor_response_values_seen: respVals,
  detail: list
}}];
